func (repo *PenetapanPemdaRepository) FindTujuanPemdaBySnapshot(
	ctx context.Context,
	snapshotID int64,
	tahun int,
) ([]domain.TujuanPemdaPenetapan, error) {
	const query = `
		SELECT id, kode_tujuan_pemda, visi, misi, tujuan_pemda, periode, tahun_aktif,
			created_date, last_modified_date, created_by, penetapan_pemda_id
		FROM tujuan_pemda_penetapan
		WHERE penetapan_pemda_id = $1 AND tahun_aktif = $2
		ORDER BY id ASC`

	rows, err := repo.DB.QueryContext(ctx, query, snapshotID, tahun)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	result := make([]domain.TujuanPemdaPenetapan, 0)
	for rows.Next() {
		var item domain.TujuanPemdaPenetapan
		if err := rows.Scan(
			&item.Id,
			&item.KodeTujuanPemda,
			&item.Visi,
			&item.Misi,
			&item.TujuanPemda,
			&item.Periode,
			&item.TahunAktif,
			&item.CreatedDate,
			&item.LastModifiedDate,
			&item.CreatedBy,
			&item.PenetapanPemdaId,
		); err != nil {
			return nil, err
		}
		result = append(result, item)
	}

	return result, rows.Err()
}

